<?php require __DIR__.'/../app/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT d.*,sp.name program,dt.name type FROM documents d LEFT JOIN study_programs sp ON sp.id=d.study_program_id LEFT JOIN document_types dt ON dt.id=d.type_id WHERE d.id=? AND d.status='published'");$s->execute([$id]);$d=$s->fetch();if(!$d)exit('Dokumen tidak ditemukan');$pdo->prepare("UPDATE documents SET views=views+1 WHERE id=?")->execute([$id]);?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($d['title'])?></title></head><body><main><p><?=e($d['type'])?> · <?=$d['year']?></p><h1><?=e($d['title'])?></h1><p><b>Penulis:</b> <?=e($d['author'])?></p><p><b>NIM:</b> <?=e($d['nim'])?></p><p><b>Program Studi:</b> <?=e($d['program'])?></p><p><b>Kata Kunci:</b> <?=e($d['keywords'])?></p><h3>Abstrak</h3><p><?=nl2br(e($d['abstract']))?></p><?php if($d['file_path']):?><a href="download.php?id=<?=$d['id']?>">Download PDF</a><?php endif;?></main></body></html>